const AR2='<defs><marker id="ar2" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L8 4L0 8z" style="fill:var(--mut)"/></marker></defs>';
const BX=(x,y,w,h,c,t1,t2,t3,fs)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" style="fill:var(--s1);stroke:${c}"/>`+T(x+w/2,y+11,t1,`text-anchor="middle" style="font-size:${fs||7.2}px;font-weight:800;fill:${c}"`)+(t2?T(x+w/2,y+21,t2,'text-anchor="middle" style="font-size:6.2px"'):'')+(t3?T(x+w/2,y+30,t3,'text-anchor="middle" style="font-size:6.2px;fill:var(--mut)"'):'');
const SGN=(x,y,s)=>`<circle cx="${x}" cy="${y}" r="7" style="fill:${s==='+'?'var(--up)':s==='−'?'var(--dn)':'var(--mut)'};fill-opacity:.85"/>`+T(x,y+3,s,'text-anchor="middle" style="font-size:9px;font-weight:800;fill:var(--bg)"');
const LESSONS2=[
 /* ---------- cấp 3: hiểu mình ---------- */
 {id:'l3-profile',t:'Hiểu mình trước khi chọn cổ phiếu',d:'Mục tiêu, thời gian, khẩu vị rủi ro',
  vis:()=>{ let g=''; const rows=[['Thời gian đầu tư','dưới 2 năm','trên 10 năm',.75],['Chịu được mức giảm','−10%','−40%',.55],['Thu nhập ổn định','bấp bênh','vững',.7]];
    rows.forEach(([n,a,b,v],i)=>{ const y=12+i*30; g+=T(6,y,n,'style="font-size:7.2px;font-weight:700"')+`<line x1="6" x2="116" y1="${y+9}" y2="${y+9}" style="stroke:var(--line2)" stroke-width="3" stroke-linecap="round"/><circle cx="${6+v*110}" cy="${y+9}" r="4.5" style="fill:var(--gold)"/>`+T(6,y+20,a,'style="font-size:5.8px;fill:var(--mut)"')+T(116,y+20,b,'text-anchor="end" style="font-size:5.8px;fill:var(--mut)"'); });
    const pr=[['Thận trọng',30,'var(--us)'],['Cân bằng',60,'var(--gold)'],['Tăng trưởng',85,'var(--up)']];
    pr.forEach(([n,p,c],i)=>{ const y=8+i*30; g+=`<rect x="128" y="${y}" width="68" height="26" rx="5" style="fill:var(--s1);stroke:${c}"/><rect x="132" y="${y+17}" width="${p*0.6}" height="4" rx="2" style="fill:${c}"/>`+T(162,y+9,n,'text-anchor="middle" style="font-size:6.6px;font-weight:800"')+T(162,y+15.5,p+'% cổ phiếu','text-anchor="middle" style="font-size:5.6px"'); });
    g+=T(100,118,'Câu trả lời của bạn quyết định tỷ trọng cổ phiếu','text-anchor="middle" '+TB);
    return sv(g,'Ba câu hỏi xác định hồ sơ nhà đầu tư và tỷ trọng cổ phiếu'); },
  f:'Tỷ trọng cổ phiếu phù hợp phụ thuộc: thời gian chưa cần tiền + mức giảm chịu được + độ ổn định thu nhập',
  pts:['Trước khi hỏi “mua mã gì”, hãy trả lời: tiền này để làm gì, khi nào cần, nếu mất 30% thì đời sống có bị ảnh hưởng không.','Phép thử thực tế: nếu danh mục giảm 30% trong ba tháng, bạn sẽ bán tháo, đứng yên hay mua thêm? Câu trả lời trung thực quyết định tỷ trọng cổ phiếu.','Người có thu nhập ổn định, còn trẻ, chưa cần tiền trong 10 năm có thể nắm nhiều cổ phiếu hơn người sắp nghỉ hưu.','Kiến thức cũng là một phần khẩu vị rủi ro: chưa đọc được BCTC thì nên dùng quỹ chỉ số nhiều hơn cổ phiếu riêng lẻ.','Viết ra một trang “chính sách đầu tư cá nhân”: mục tiêu, tỷ trọng, quy tắc mua bán. Đọc lại mỗi khi thị trường làm bạn hoảng.'],
  thr:[['Thận trọng','Khoảng 20–40% cổ phiếu, còn lại tiền gửi, trái phiếu'],['Cân bằng','Khoảng 50–70% cổ phiếu'],['Tăng trưởng','Khoảng 80–100% cổ phiếu, thời gian trên 10 năm']],
  hook:'<b>Mẹo nhớ:</b> danh mục tốt nhất là danh mục bạn giữ được qua cả mùa thị trường sập.',src:'CFA Institute, Elements of an Investment Policy Statement for Individual Investors (2010); Vanguard, Investor Questionnaire.'},
 {id:'l3-inflation',t:'Lạm phát và lợi nhuận thực',d:'Tiền đứng yên là tiền mất giá',
  vis:()=>{ let g=''; const yrs=[[0,100],[5,82.2],[10,67.6],[15,55.5],[20,45.6]];
    yrs.forEach(([y,v],i)=>{ const x=18+i*38, h=v*0.62; g+=`<rect x="${x}" y="${94-h}" width="26" height="${h}" rx="3" style="fill:var(--gold);fill-opacity:${1-i*.15}"/>`+T(x+13,90-h,fmt(v,1),'text-anchor="middle" style="font-size:7.5px;font-weight:800"')+T(x+13,103,y?'sau '+y+' năm':'hôm nay','text-anchor="middle" style="font-size:6.5px"'); });
    g+=T(100,10,'Sức mua của 100 triệu đồng nếu lạm phát 4%/năm','text-anchor="middle" '+TB)+T(100,117,'Tiền gửi phải sinh lời hơn lạm phát mới thật sự tăng','text-anchor="middle" '+TS);
    return sv(g,'Sức mua của 100 triệu giảm dần theo lạm phát 4% mỗi năm'); },
  f:'Lợi nhuận thực = (1 + lợi nhuận danh nghĩa) ÷ (1 + lạm phát) − 1 ≈ danh nghĩa − lạm phát',
  pts:['Lạm phát (CPI) Việt Nam khoảng 3–4%/năm trong vài năm gần đây. Với 4%/năm, sức mua của tiền giảm một nửa sau khoảng 18 năm.','Gửi tiết kiệm 5% khi lạm phát 3,5% thì lợi nhuận thực chỉ khoảng 1,4%/năm.','Cổ phiếu là quyền sở hữu doanh nghiệp — doanh nghiệp tăng giá bán theo lạm phát — nên về dài hạn thường giữ được sức mua tốt hơn tiền mặt và trái phiếu lãi cố định.','Lạm phát cao làm lãi suất tăng, định giá cổ phiếu thường giảm trong ngắn hạn — ngắn hạn và dài hạn có thể ngược nhau.','Luôn so sánh mục tiêu tích sản bằng “tiền hôm nay”: 5 tỷ sau 20 năm chỉ tương đương khoảng 2,3 tỷ bây giờ nếu lạm phát 4%.'],
  thr:[['Lạm phát 4%/năm','Sức mua giảm một nửa sau ≈ 18 năm'],['Lợi nhuận thực âm','Đang nghèo đi dù số dư tăng'],['Mục tiêu tích sản','Luôn quy về tiền hôm nay']],
  hook:'<b>Mẹo nhớ:</b> lạm phát là khoản thuế vô hình đánh vào người giữ tiền mặt.',src:'Tổng cục Thống kê, chỉ số giá tiêu dùng (CPI); Fisher, The Theory of Interest (1930).'},
 /* ---------- cấp 4: đọc BCTC ---------- */
 {id:'l4-bs',t:'Bảng cân đối kế toán chi tiết',d:'Tài sản ngắn hạn, dài hạn và nguồn vốn',
  vis:()=>{ let g=''; const L=[['Tiền & tương đương',18,'var(--up)'],['Phải thu',20,'var(--us)'],['Hàng tồn kho',22,'var(--gold)'],['TSCĐ, XDCB',30,'var(--mut)'],['Đầu tư dài hạn',10,'var(--vn)']], R=[['Nợ ngắn hạn',30,'var(--dn)'],['Nợ dài hạn',20,'var(--dn)'],['Vốn chủ sở hữu',50,'var(--up)']];
    let y=18; L.forEach(([n,h,c])=>{ g+=`<rect x="14" y="${y}" width="74" height="${h*0.9-1}" rx="2" style="fill:${c};fill-opacity:.55"/>`+T(51,y+h*0.45+2,n,'text-anchor="middle" style="font-size:6.6px;font-weight:700"'); y+=h*0.9; });
    y=18; R.forEach(([n,h,c],i)=>{ g+=`<rect x="112" y="${y}" width="74" height="${h*0.9-1}" rx="2" style="fill:${c};fill-opacity:${i===1?.35:.55}"/>`+T(149,y+h*0.45+2,n,'text-anchor="middle" style="font-size:6.6px;font-weight:700"'); y+=h*0.9; });
    g+=T(51,12,'TÀI SẢN','text-anchor="middle" '+TB)+T(149,12,'NGUỒN VỐN','text-anchor="middle" '+TB)+T(100,64,'=','text-anchor="middle" style="font-size:14px;font-weight:800"');
    g+=T(51,118,'Có gì','text-anchor="middle" '+TS)+T(149,118,'Tiền từ đâu','text-anchor="middle" '+TS);
    return sv(g,'Cấu trúc bảng cân đối kế toán: tài sản bằng nợ cộng vốn chủ'); },
  f:'Vốn lưu động = Tài sản ngắn hạn − Nợ ngắn hạn · Nợ vay ròng = Vay ngắn + dài hạn − Tiền và tương đương tiền',
  pts:['Tài sản ngắn hạn (dưới 12 tháng): tiền, đầu tư tài chính ngắn hạn, phải thu khách hàng, trả trước cho người bán, phải thu khác, hàng tồn kho.','Tài sản dài hạn: tài sản cố định, xây dựng cơ bản dở dang, bất động sản đầu tư, đầu tư vào công ty liên kết, lợi thế thương mại.','Nợ phải trả: phải trả người bán, người mua trả tiền trước (rất lớn ở doanh nghiệp bất động sản), vay ngắn hạn và dài hạn, trái phiếu.','Vốn chủ sở hữu: vốn góp, thặng dư vốn, lợi nhuận sau thuế chưa phân phối, lợi ích cổ đông không kiểm soát.','Đọc theo xu hướng: so sánh 4–8 kỳ liên tiếp. Khoản nào tăng nhanh bất thường so với doanh thu là chỗ cần đọc thuyết minh.','Chú ý “phải thu khác” và “trả trước cho người bán” lớn — ở Việt Nam đôi khi là kênh chuyển tiền cho bên liên quan.'],
  thr:[['Nợ vay ròng ÷ Vốn chủ dưới 1','Đòn bẩy vừa phải với doanh nghiệp sản xuất'],['Tài sản ngắn hạn lớn hơn nợ ngắn hạn','Đủ khả năng trả nợ đến hạn'],['Phải thu khác, trả trước tăng mạnh','Đọc thuyết minh: đối tượng là ai?']],
  hook:'<b>Mẹo nhớ:</b> bên trái là “có gì”, bên phải là “tiền từ đâu” — hai bên luôn bằng nhau.',src:'Thông tư 200/2014/TT-BTC (mẫu B01-DN); Chuẩn mực kế toán Việt Nam VAS 21.'},
 {id:'l4-is',t:'Báo cáo kết quả kinh doanh chi tiết',d:'Lợi nhuận đến từ đâu, có lặp lại không',
  vis:()=>{ const st=[['Doanh thu',100,0,'var(--us)'],['Giá vốn',-70,0,'var(--dn)'],['LN gộp',30,1,'var(--up)'],['Bán hàng & QL',-14,0,'var(--dn)'],['Tài chính',-2,0,'var(--dn)'],['LN khác',4,0,'var(--gold)'],['Thuế',-4,0,'var(--dn)'],['LNST',14,1,'var(--up)']];
    const Y=v=>96-v*0.78; let run=0, g=''; const w=20;
    st.forEach(([n,v,tot,c],i)=>{ const x=8+i*23.5; let a,b; if(tot){ a=0;b=v; run=v; } else { a=run; b=run+v; run=b; }
      g+=`<rect x="${x}" y="${Y(Math.max(a,b))}" width="${w}" height="${Math.max(1,Math.abs(b-a)*0.78)}" rx="2" style="fill:${c};fill-opacity:.8"/>`+T(x+w/2,Y(Math.max(a,b))-2,(v>0&&!tot&&i?'+':'')+v,'text-anchor="middle" style="font-size:6.5px;font-weight:700"')+T(x+w/2,106,n.split(' ')[0],'text-anchor="middle" style="font-size:5.8px"')+(n.split(' ').length>1?T(x+w/2,113,n.split(' ').slice(1).join(' '),'text-anchor="middle" style="font-size:5.8px"'):''); });
    g+=T(196,12,'Vàng: lợi nhuận một lần,','text-anchor="end" style="font-size:6.3px;fill:var(--gold)"')+T(196,21,'loại khi định giá','text-anchor="end" style="font-size:6.3px;fill:var(--gold)"');
    return sv(g,'Thác lợi nhuận từ doanh thu đến lợi nhuận sau thuế'); },
  f:'LN thuần từ HĐKD = LN gộp + DT tài chính − CP tài chính + LN liên doanh − CP bán hàng − CP quản lý',
  pts:['Doanh thu thuần đã trừ giảm giá, hàng bán bị trả lại. Giá vốn hàng bán là chi phí trực tiếp tạo ra sản phẩm.','Lợi nhuận gộp ÷ doanh thu = biên gộp, đo sức mạnh định giá. Chi phí bán hàng và quản lý đo hiệu quả vận hành.','Doanh thu và chi phí tài chính gồm lãi tiền gửi, lãi vay, chênh lệch tỷ giá, lãi lỗ đầu tư chứng khoán — dễ biến động.','“Lợi nhuận khác” và lãi thanh lý tài sản, đánh giá lại khoản đầu tư là một lần. Khi định giá, dùng lợi nhuận cốt lõi đã loại các khoản này.','EPS tính trên lợi nhuận sau thuế của cổ đông công ty mẹ, không phải tổng lợi nhuận hợp nhất (có phần của cổ đông không kiểm soát).','So sánh quý này với cùng quý năm trước (YoY) để loại mùa vụ; dùng tổng 4 quý gần nhất (TTM) để tính P/E.'],
  thr:[['Lợi nhuận khác trên 20% LNTT','Lợi nhuận kém bền vững'],['Chi phí lãi vay trên 30% LN gộp','Đòn bẩy đang ăn lợi nhuận'],['LN tăng nhanh hơn DT nhiều quý','Biên mở rộng thật — hoặc yếu tố bất thường']],
  hook:'<b>Mẹo nhớ:</b> hỏi mỗi dòng lợi nhuận một câu: “năm sau còn lặp lại không?”',src:'Thông tư 200/2014/TT-BTC (mẫu B02-DN); VAS 01, VAS 14.'},
 {id:'l4-ratios',t:'Bộ chỉ số tài chính cốt lõi',d:'Thanh khoản, đòn bẩy, hiệu quả, sinh lời',
  vis:()=>{ const q=[['THANH KHOẢN','var(--us)',['Hiện hành = TSNH ÷ Nợ NH','Nhanh = (TSNH − HTK) ÷ Nợ NH']],['ĐÒN BẨY','var(--dn)',['Nợ vay ròng ÷ EBITDA','Trả lãi = EBIT ÷ Chi phí lãi']],['HIỆU QUẢ','var(--gold)',['Vòng quay TS = DT ÷ Tổng TS','Ngày thu tiền = PT ÷ DT × 365']],['SINH LỜI','var(--up)',['ROE = LNST ÷ Vốn CSH','ROIC = EBIT(1−t) ÷ Vốn ĐT']]];
    let g=''; q.forEach(([n,c,f],i)=>{ const x=6+(i%2)*97, y=8+Math.floor(i/2)*56; g+=`<rect x="${x}" y="${y}" width="91" height="50" rx="7" style="fill:var(--s1);stroke:${c}"/>`+T(x+45.5,y+13,n,`text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:${c}"`)+f.map((t,k)=>T(x+45.5,y+27+k*11,t,'text-anchor="middle" style="font-size:5.4px"')).join(''); });
    return sv(g,'Bốn nhóm chỉ số tài chính cốt lõi'); },
  f:'Đọc chỉ số theo xu hướng 3–5 năm và so với trung vị ngành — một con số đơn lẻ không nói lên nhiều',
  pts:['Thanh khoản: hệ số hiện hành, hệ số nhanh, hệ số tiền mặt — doanh nghiệp có trả được nợ đến hạn không.','Đòn bẩy: nợ vay ÷ vốn chủ, nợ vay ròng ÷ EBITDA (bao nhiêu năm lợi nhuận hoạt động để trả hết nợ), khả năng trả lãi (EBIT ÷ chi phí lãi vay).','Hiệu quả: vòng quay tài sản, số ngày thu tiền, số ngày tồn kho, số ngày trả tiền người bán — tiền bị “chôn” bao lâu.','Sinh lời: biên gộp, biên ròng, ROA, ROE, ROIC. ROE cao nhờ đòn bẩy kém chất lượng hơn ROE cao nhờ biên lợi nhuận (xem bài DuPont).','Ngân hàng, bảo hiểm, chứng khoán dùng bộ chỉ số riêng (xem bài “Đọc BCTC theo ngành”).','Trang chi tiết mỗi mã trong ứng dụng đã tính sẵn phần lớn các chỉ số này.'],
  thr:[['Hệ số hiện hành trên 1,2','Thanh khoản ổn'],['Nợ vay ròng ÷ EBITDA dưới 3','Đòn bẩy chấp nhận được'],['Khả năng trả lãi trên 3 lần','Không bị áp lực lãi vay']],
  hook:'<b>Mẹo nhớ:</b> bốn câu hỏi — trả nợ được không, vay nhiều không, dùng tài sản giỏi không, kiếm lời giỏi không.',src:'CFA Institute, Financial Analysis Techniques (CFA Program Curriculum Level I).'},
 {id:'l4-notes',t:'Thuyết minh và ý kiến kiểm toán',d:'Nơi ẩn chứa thông tin quan trọng nhất',
  vis:()=>{ const op=[['Chấp nhận toàn phần','An tâm','var(--up)'],['Có đoạn nhấn mạnh','Đọc kỹ đoạn đó','var(--us)'],['Ngoại trừ','Cẩn trọng cao','var(--gold)'],['Trái ngược / Từ chối','Tránh xa','var(--dn)']];
    let g=T(100,12,'Bốn mức ý kiến kiểm toán','text-anchor="middle" '+TB); op.forEach(([a,b,c],i)=>{ const y=20+i*22; g+=`<rect x="8" y="${y}" width="${124-i*12}" height="18" rx="5" style="fill:${c};fill-opacity:.75"/>`+T(14,y+12,a,'style="font-size:7px;font-weight:800;fill:var(--bg)"')+T(194,y+12,b,'text-anchor="end" style="font-size:6.8px;font-weight:700"'); });
    g+=T(100,118,'Đọc ý kiến kiểm toán trước, số liệu sau','text-anchor="middle" '+TS);
    return sv(g,'Các mức ý kiến kiểm toán từ an toàn đến rủi ro'); },
  f:'Thứ tự đọc: Ý kiến kiểm toán → Chính sách kế toán → Bên liên quan → Vay nợ, bảo lãnh → Sự kiện sau ngày kết thúc kỳ',
  pts:['Ý kiến kiểm toán có bốn mức: chấp nhận toàn phần; ngoại trừ (một phần số liệu không đủ bằng chứng hoặc sai); trái ngược; từ chối đưa ra ý kiến. Có thể kèm đoạn “vấn đề cần nhấn mạnh”, ví dụ nghi ngờ khả năng hoạt động liên tục.','Cổ phiếu có ý kiến ngoại trừ, trái ngược hoặc từ chối có thể bị đưa vào diện cảnh báo, kiểm soát, thậm chí hủy niêm yết nếu lặp lại.','Thuyết minh cho biết chi tiết từng khoản: vay ai, lãi suất bao nhiêu, tài sản thế chấp, phải thu của ai, giao dịch với công ty của lãnh đạo.','So sánh số liệu trước và sau kiểm toán (hoặc soát xét bán niên): chênh lệch lợi nhuận lớn là dấu hiệu kế toán thiếu thận trọng.','BCTC hợp nhất thể hiện cả tập đoàn; BCTC riêng chỉ công ty mẹ. Cổ tức chi từ lợi nhuận chưa phân phối của công ty mẹ.','Đổi công ty kiểm toán thường xuyên, nộp báo cáo trễ hạn — cờ vàng về quản trị.'],
  thr:[['Ý kiến ngoại trừ','Tìm hiểu lý do trước khi mua'],['Từ chối hoặc trái ngược','Loại khỏi danh sách'],['Chênh lệch trước – sau kiểm toán lớn','Giảm độ tin cậy với số liệu tự lập']],
  hook:'<b>Mẹo nhớ:</b> con số ở trang đầu, sự thật ở thuyết minh.',src:'Chuẩn mực kiểm toán Việt Nam VSA 700, 705, 706; Thông tư 96/2020/TT-BTC về công bố thông tin.'},
 /* ---------- cấp 5: dòng tiền & sức khỏe ---------- */
 {id:'l5-cf3',t:'Ba dòng tiền và vòng đời doanh nghiệp',d:'Đọc dấu cộng trừ của CFO, CFI, CFF',
  vis:()=>{ let g=''; const hd=['Kinh doanh','Đầu tư','Tài chính']; const st=[['Khởi nghiệp','−','−','+'],['Tăng trưởng','+','−','+'],['Trưởng thành','+','−','−'],['Suy thoái','−','+','−']];
    hd.forEach((h,i)=>g+=T(96+i*36,14,h,'text-anchor="middle" style="font-size:6.8px;font-weight:800"'));
    st.forEach(([n,a,b,c],r)=>{ const y=30+r*22; g+=`<rect x="6" y="${y-11}" width="188" height="19" rx="5" style="fill:${r===2?'var(--gold-soft, rgba(216,174,87,.15))':'var(--s1)'};stroke:var(--line)"/>`+T(12,y+2,n,'style="font-size:7.4px;font-weight:700"')+SGN(96,y-1.5,a)+SGN(132,y-1.5,b)+SGN(168,y-1.5,c); });
    g+=T(100,120,'Doanh nghiệp tốt để tích sản thường ở pha trưởng thành','text-anchor="middle" '+TS);
    return sv(g,'Dấu của ba dòng tiền theo từng pha vòng đời doanh nghiệp'); },
  f:'Tiền cuối kỳ = Tiền đầu kỳ + Lưu chuyển từ kinh doanh (CFO) + từ đầu tư (CFI) + từ tài chính (CFF)',
  pts:['CFO — dòng tiền kinh doanh: tiền thu từ khách hàng trừ tiền trả nhà cung cấp, nhân viên, lãi vay, thuế. Đây là “máu” của doanh nghiệp.','CFI — dòng tiền đầu tư: chi mua sắm tài sản cố định (capex), góp vốn, mua bán công ty con, gửi tiền có kỳ hạn; thường âm khi doanh nghiệp mở rộng.','CFF — dòng tiền tài chính: vay và trả nợ, phát hành cổ phiếu, trả cổ tức tiền mặt.','Phần lớn doanh nghiệp Việt Nam lập CFO theo phương pháp gián tiếp: bắt đầu từ lợi nhuận trước thuế, cộng khấu hao, điều chỉnh thay đổi phải thu, tồn kho, phải trả.','Nhìn tổ hợp dấu để biết pha vòng đời: doanh nghiệp trưởng thành có CFO dương, dùng tiền đó để đầu tư và trả nợ, trả cổ tức (+, −, −).','Đáng lo nhất: lợi nhuận dương nhiều năm nhưng CFO âm, phải liên tục vay mới (CFF dương) để bù.'],
  thr:[['CFO ÷ LNST trên 1 (3–5 năm)','Lợi nhuận thành tiền thật'],['CFO âm nhiều năm khi có lãi','Cờ đỏ chất lượng lợi nhuận'],['Cổ tức trả bằng tiền vay','Không bền vững']],
  hook:'<b>Mẹo nhớ:</b> lợi nhuận là ý kiến, tiền mặt là sự thật.',src:'VAS 24 (Báo cáo lưu chuyển tiền tệ); Dickinson (2011), Cash Flow Patterns as a Proxy for Firm Life Cycle, The Accounting Review 86(6).'},
 {id:'l5-capex',t:'Capex, khấu hao và lợi nhuận chủ sở hữu',d:'Tiền để đứng yên và tiền để lớn lên',
  vis:()=>{ let g=''; const parts=[['Capex bảo trì',30,'var(--dn)'],['Capex mở rộng',35,'var(--us)'],['Tiền tự do',35,'var(--up)']]; let x=10;
    g+=T(100,14,'Dòng tiền kinh doanh = 100','text-anchor="middle" '+TB);
    parts.forEach(([n,v,c])=>{ const w=v*1.8; g+=`<rect x="${x}" y="24" width="${w-2}" height="28" rx="4" style="fill:${c};fill-opacity:.7"/>`+T(x+w/2-1,36,n,'text-anchor="middle" style="font-size:6.6px;font-weight:800;fill:var(--bg)"')+T(x+w/2-1,47,v,'text-anchor="middle" style="font-size:8px;font-weight:800;fill:var(--bg)"'); x+=w; });
    g+=T(10,70,'≈ khấu hao: giữ năng lực hiện có','style="font-size:6.5px;fill:var(--dn)"')+T(10,82,'Mở rộng: chỉ tốt khi ROIC của dự án > chi phí vốn','style="font-size:6.5px;fill:var(--us)"')+T(10,94,'Tiền tự do: trả cổ tức, mua lại cổ phiếu, trả nợ','style="font-size:6.5px;fill:var(--up)"');
    g+=T(100,116,'Lợi nhuận chủ sở hữu = LNST + KH − Capex bảo trì','text-anchor="middle" '+TB);
    return sv(g,'Phân bổ dòng tiền kinh doanh: capex bảo trì, capex mở rộng, tiền tự do'); },
  f:'Lợi nhuận chủ sở hữu (Buffett) = LNST + Khấu hao − Capex bảo trì − Tăng vốn lưu động cần thiết',
  pts:['Capex là tiền chi mua, xây tài sản cố định — xem dòng “Tiền chi để mua sắm, xây dựng TSCĐ” trên báo cáo lưu chuyển tiền tệ.','Capex bảo trì giữ nguyên năng lực sản xuất (thay máy cũ); capex mở rộng tạo tăng trưởng mới. Báo cáo không tách riêng; ước lượng thô: capex bảo trì ≈ khấu hao.','FCF = CFO − toàn bộ capex. Doanh nghiệp đang mở rộng mạnh có FCF âm tạm thời — không xấu nếu dự án có ROIC cao.','Doanh nghiệp “thâm dụng vốn” (thép, hàng không, điện) cần capex lớn mãi mãi để đứng yên; doanh nghiệp “nhẹ vốn” (phần mềm, bán lẻ online, thương hiệu tiêu dùng) giữ lại nhiều tiền tự do hơn.','Xây dựng cơ bản dở dang kéo dài nhiều năm mà không chuyển thành tài sản tạo doanh thu là dấu hiệu dự án gặp vấn đề.'],
  thr:[['Capex ÷ Khấu hao gần 1','Chủ yếu bảo trì, tăng trưởng thấp'],['Capex ÷ Khấu hao trên 2','Đang mở rộng mạnh — kiểm tra nguồn vốn'],['FCF dương đều nhiều năm','Có thể trả cổ tức bền vững']],
  hook:'<b>Mẹo nhớ:</b> khấu hao là chi phí thật — máy móc rồi sẽ phải thay.',src:'Buffett, Thư gửi cổ đông Berkshire Hathaway 1986 (Owner earnings); Greenwald và cộng sự, Value Investing: From Graham to Buffett and Beyond (2001).'},
 {id:'l5-quality',t:'Chất lượng lợi nhuận',d:'Lợi nhuận có biến thành tiền không?',
  vis:()=>{ const X=i=>28+i*36, Y=v=>62-v*0.42; let g=`<line class="grid-l" x1="20" x2="190" y1="${Y(0)}" y2="${Y(0)}"/>`;
    const A=[[60,64],[70,75],[80,86],[90,94],[100,108]], B=[[60,40],[80,20],[100,-10],[125,-30],[150,-45]];
    const pl=(arr,k,c,dash)=>`<path d="${arr.map((p,i)=>(i?'L':'M')+X(i)+' '+Y(p[k])).join(' ')}" fill="none" style="stroke:${c}" stroke-width="1.8"${dash?' stroke-dasharray="3 2"':''}/>`;
    g+=`<g transform="translate(0,0) scale(.5,1)">${''}</g>`;
    const half=(arr,dx,c)=>arr.map((p,i)=>`<circle cx="${(X(i)*0.45+dx).toFixed(1)}" cy="${Y(p[0])}" r="2" style="fill:var(--gold)"/><circle cx="${(X(i)*0.45+dx).toFixed(1)}" cy="${Y(p[1])}" r="2" style="fill:${c}"/>`).join('')+`<path d="${arr.map((p,i)=>(i?'L':'M')+(X(i)*0.45+dx).toFixed(1)+' '+Y(p[0])).join(' ')}" fill="none" style="stroke:var(--gold)" stroke-width="1.6"/><path d="${arr.map((p,i)=>(i?'L':'M')+(X(i)*0.45+dx).toFixed(1)+' '+Y(p[1])).join(' ')}" fill="none" style="stroke:${c}" stroke-width="1.6" stroke-dasharray="3 2"/>`;
    g+=half(A,0,'var(--up)')+half(B,98,'var(--dn)');
    g+=T(45,96,'Công ty A','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--up)"')+T(45,106,'tiền đi cùng lợi nhuận','text-anchor="middle" style="font-size:6.3px"')+T(143,96,'Công ty B','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--dn)"')+T(143,106,'lợi nhuận tăng, tiền âm','text-anchor="middle" style="font-size:6.3px"');
    g+=T(100,118,'Vàng: lợi nhuận · Đứt nét: dòng tiền KD · minh họa 5 năm','text-anchor="middle" style="font-size:6.4px"');
    return sv(g,'So sánh lợi nhuận và dòng tiền của hai doanh nghiệp minh họa'); },
  f:'Tỷ lệ dồn tích = (LNST − CFO) ÷ Tổng tài sản bình quân · Mong muốn: CFO ÷ LNST ≥ 1',
  pts:['Kế toán dồn tích ghi nhận doanh thu khi bán, không phải khi thu tiền — nên lợi nhuận và tiền có thể lệch nhau, nhất là khi bán chịu.','Nghiên cứu của Sloan (1996): doanh nghiệp có phần lợi nhuận “dồn tích” lớn (không đi kèm tiền) thường có lợi nhuận và giá cổ phiếu kém hơn về sau.','Dấu hiệu lợi nhuận kém chất lượng: phải thu tăng nhanh hơn doanh thu, tồn kho phình to, vốn hóa chi phí lãi vay vào tài sản, hoàn nhập dự phòng, lãi đánh giá lại.','Kiểm tra số ngày thu tiền (DSO): tăng đột biến là doanh nghiệp đang nới lỏng bán chịu để “đẩy” doanh thu.','Lợi nhuận chất lượng cao: CFO xấp xỉ hoặc lớn hơn LNST nhiều năm, biên lợi nhuận ổn định, ít khoản bất thường.'],
  thr:[['Tỷ lệ dồn tích trên 10% tài sản','Cảnh báo'],['DSO tăng hơn 30% trong một năm','Soi chính sách bán chịu'],['CFO ÷ LNST trung bình 3 năm dưới 0,5','Lợi nhuận khó tin']],
  hook:'<b>Mẹo nhớ:</b> doanh thu chưa thu được tiền chỉ là một lời hứa.',src:'Sloan (1996), Do Stock Prices Fully Reflect Information in Accruals and Cash Flows about Future Earnings?, The Accounting Review 71(3); Schilit, Perler & Engelhart, Financial Shenanigans (4th ed., 2018).'},
 {id:'l5-redflags',t:'12 cờ đỏ trong báo cáo tài chính',d:'Danh sách kiểm tra trước khi xuống tiền',
  vis:()=>{ const f=['CFO âm khi có lãi','Phải thu tăng vọt','Phải thu khác lớn','Tồn kho phình to','Lãi từ thanh lý','Vay ngắn đầu tư dài','Phát hành liên tục','Bên liên quan lớn','Kiểm toán ngoại trừ','Lãnh đạo bán ra','Lệch sau kiểm toán','XDCB dở dang lâu'];
    let g=''; f.forEach((t,i)=>{ const x=4+(i%3)*65, y=8+Math.floor(i/3)*28; g+=`<rect x="${x}" y="${y}" width="62" height="24" rx="5" style="fill:var(--s1);stroke:var(--dn)" stroke-opacity=".6"/><path d="M${x+6} ${y+18} V${y+5} l7 3 -7 3" style="fill:var(--dn);stroke:var(--dn)" stroke-width="1"/>`;
      const w=t.split(' '); const l1=w.slice(0,Math.ceil(w.length/2)).join(' '), l2=w.slice(Math.ceil(w.length/2)).join(' '); g+=T(x+37,y+11,l1,'text-anchor="middle" style="font-size:6.2px;font-weight:700"')+T(x+37,y+19,l2,'text-anchor="middle" style="font-size:6.2px;font-weight:700"'); });
    return sv(g,'Mười hai cờ đỏ thường gặp trong báo cáo tài chính'); },
  f:'Một cờ đỏ = cần lời giải thích · Ba cờ đỏ trở lên = bỏ qua, thị trường còn hàng trăm lựa chọn khác',
  pts:['1. Lợi nhuận dương nhiều năm nhưng dòng tiền kinh doanh âm.','2. Phải thu khách hàng tăng nhanh hơn doanh thu nhiều kỳ liên tiếp.','3. “Phải thu khác”, “trả trước cho người bán”, “cho vay” lớn và không rõ đối tượng.','4. Hàng tồn kho tăng nhanh hơn doanh thu (hàng khó bán, có thể phải trích lập dự phòng).','5. Lợi nhuận đến chủ yếu từ thanh lý tài sản, đánh giá lại, hoàn nhập dự phòng.','6. Vay ngắn hạn để đầu tư dự án dài hạn (lệch kỳ hạn, dễ gãy khi tín dụng thắt chặt).','7. Phát hành tăng vốn liên tục, EPS bị pha loãng, tiền huy động dùng sai mục đích công bố.','8. Giao dịch lớn với bên liên quan: mua bán, cho vay, bảo lãnh cho công ty của lãnh đạo.','9. Ý kiến kiểm toán ngoại trừ, đổi công ty kiểm toán, nộp báo cáo trễ hạn.','10. Lãnh đạo, cổ đông lớn bán ra mạnh; cổ phiếu cầm cố bị bán giải chấp.','11. Lợi nhuận sau kiểm toán chênh lệch lớn so với báo cáo tự lập.','12. Xây dựng cơ bản dở dang, vốn hóa lãi vay lớn và kéo dài nhiều năm.'],
  thr:[['0 cờ đỏ','Tiếp tục định giá'],['1–2 cờ đỏ','Tìm lời giải thích trong thuyết minh, báo cáo thường niên'],['3+ cờ đỏ','Loại']],
  hook:'<b>Mẹo nhớ:</b> bạn không cần đúng ở mọi cổ phiếu — chỉ cần tránh những cổ phiếu có thể làm mất trắng.',src:'Schilit, Perler & Engelhart, Financial Shenanigans (2018); Beneish (1999), The Detection of Earnings Manipulation, Financial Analysts Journal 55(5).'},
 {id:'l5-practice',t:'Thực hành: đọc BCTC trong 15 phút',d:'Ví dụ giả định có lời giải từng bước',interactive:'practice',
  vis:()=>{ const yrs=['2023','2024','2025'], ni=[100,130,180], cfo=[110,60,-20], Y=v=>78-v*0.28; let g=`<line class="grid-l" x1="14" x2="190" y1="${Y(0)}" y2="${Y(0)}"/>`;
    yrs.forEach((y,i)=>{ const x=30+i*56; g+=`<rect x="${x}" y="${Y(ni[i])}" width="18" height="${ni[i]*0.28}" rx="2" style="fill:var(--gold);fill-opacity:.8"/>`+T(x+9,Y(ni[i])-3,ni[i],'text-anchor="middle" style="font-size:7px;font-weight:700"');
      const top=cfo[i]>=0?Y(cfo[i]):Y(0), h=Math.abs(cfo[i])*0.28; g+=`<rect x="${x+20}" y="${top}" width="18" height="${Math.max(1,h)}" rx="2" style="fill:${cfo[i]>=0?'var(--up)':'var(--dn)'};fill-opacity:.8"/>`+T(x+29,cfo[i]>=0?Y(cfo[i])-3:Y(cfo[i])+9,cfo[i],'text-anchor="middle" style="font-size:7px;font-weight:700"')+T(x+19,107,y,'text-anchor="middle" style="font-size:7px"'); });
    g+=T(100,9,'Công ty giả định Sen Vàng · Vàng: LNST · Xanh/đỏ: CFO','text-anchor="middle" style="font-size:6.4px"')+T(100,120,'Lợi nhuận tăng 80% nhưng tiền âm — vì sao?','text-anchor="middle" '+TB);
    return sv(g,'Ví dụ giả định: lợi nhuận tăng trong khi dòng tiền kinh doanh giảm'); },
  f:'Quy trình 6 bước: Tăng trưởng → Biên lợi nhuận → Dòng tiền → Vốn lưu động → Nợ vay → Kết luận',
  pts:['Bước 1 — Tăng trưởng: doanh thu, lợi nhuận tăng bao nhiêu mỗi năm, có đều không.','Bước 2 — Biên lợi nhuận: biên gộp, biên ròng đang mở rộng hay co lại.','Bước 3 — Dòng tiền: CFO so với LNST.','Bước 4 — Vốn lưu động: phải thu, tồn kho tăng nhanh hơn doanh thu không (tính số ngày thu tiền, số ngày tồn kho).','Bước 5 — Nợ: tiền thiếu được bù bằng vay hay phát hành; nợ vay ÷ vốn chủ thay đổi ra sao.','Bước 6 — Kết luận bằng một câu: tăng trưởng này lành mạnh hay “nóng”. Làm bài thực hành bên dưới, tự trả lời trước khi bấm xem đáp án.'],
  thr:[['Doanh thu và CFO cùng tăng','Tăng trưởng lành mạnh'],['Doanh thu tăng, CFO giảm, nợ tăng','Tăng trưởng “nóng”, cần lời giải thích']],
  hook:'<b>Mẹo nhớ:</b> câu chuyện tăng trưởng nào cũng phải đi qua được bảng lưu chuyển tiền tệ.',src:'Ví dụ giả định do ứng dụng soạn để luyện tập; phương pháp theo CFA Institute, Financial Reporting and Analysis.'},
 /* ---------- cấp 7: chọn cổ phiếu ---------- */
 {id:'l7-process',t:'Quy trình chọn cổ phiếu 5 bước',d:'Từ 1.000 mã xuống vài mã đáng mua',act:'screen',
  vis:()=>{ const st=[['1.000 mã','Sàng lọc định lượng',180],['≈ 100','Đọc BCTC, loại cờ đỏ',148],['≈ 30','Ngành, hào, lãnh đạo',116],['≈ 10','Định giá, biên an toàn',84],['3–5','Luận điểm & kế hoạch',52]];
    let g=''; st.forEach(([n,t,w],i)=>{ const y=8+i*22, ww=w*0.55, x=52-ww/2; g+=`<path d="M${x} ${y} h${ww} l-9 18 h${-(ww-18)} z" style="fill:var(--gold);fill-opacity:${.6+i*.1}"/>`+T(52,y+12,n,'text-anchor="middle" style="font-size:7.6px;font-weight:800;fill:var(--gold-ink)"')+`<line x1="${52+ww/2-2}" x2="112" y1="${y+9}" y2="${y+9}" style="stroke:var(--line2)" stroke-dasharray="2 2"/>`+T(116,y+12,t,'style="font-size:7px"'); });
    return sv(g,'Phễu năm bước chọn cổ phiếu'); },
  f:'Doanh nghiệp tốt + Giá hợp lý + Biên an toàn + Kế hoạch rõ ràng = Quyết định đầu tư',
  pts:['Bước 1 — Sàng lọc định lượng: dùng bộ lọc La Bàn (thử các bộ trọng số Giá trị, Chất lượng, Cổ tức…) để giữ lại khoảng 100 mã có điểm cao, không cờ đỏ.','Bước 2 — Đọc BCTC 5 năm: tăng trưởng, biên lợi nhuận, dòng tiền, nợ (cấp 4–5). Loại mã có từ 3 cờ đỏ.','Bước 3 — Định tính: ngành có hấp dẫn không, doanh nghiệp có hào kinh tế không, lãnh đạo có đáng tin không.','Bước 4 — Định giá: P/E, P/B so với lịch sử và ngành, DCF, định giá ngược. Chỉ mua khi giá thấp hơn giá trị ước tính một khoảng an toàn (thường 20–30%).','Bước 5 — Viết luận điểm đầu tư, xác định tỷ trọng (thường không quá 10–15% danh mục cho một mã) và điều kiện bán.','Lặp lại mỗi quý khi có BCTC mới — danh sách theo dõi thay đổi theo thời gian.'],
  thr:[['Số mã nên nắm giữ','Khoảng 8–20 mã, hoặc một quỹ chỉ số'],['Tỷ trọng tối đa một mã','10–15% danh mục'],['Biên an toàn','Mua dưới giá trị ước tính 20–30%']],
  hook:'<b>Mẹo nhớ:</b> phễu càng nhiều tầng, càng ít quyết định cảm tính.',src:'Graham & Dodd, Security Analysis (6th ed., 2008); Lynch, One Up on Wall Street (1989); Greenblatt, The Little Book That Still Beats the Market (2010).'},
 {id:'l7-industry',t:'Phân tích ngành: 5 áp lực cạnh tranh',d:'Ngành tốt giúp doanh nghiệp tốt dễ thắng',
  vis:()=>{ let g=AR2; const c=[100,62]; const n=[[100,14,'Đối thủ mới','Rào cản gia nhập?'],[100,110,'Sản phẩm thay thế','Dễ bị thay thế?'],[36,62,'Nhà cung cấp','Họ ép giá được?'],[164,62,'Khách hàng','Họ ép giá được?']];
    n.forEach(([x,y,a,b])=>{ g+=`<line x1="${x}" y1="${y}" x2="${c[0]+(x-c[0])*0.32}" y2="${c[1]+(y-c[1])*0.32}" style="stroke:var(--mut)" marker-end="url(#ar2)"/>`+`<rect x="${x-33}" y="${y-10}" width="66" height="20" rx="5" style="fill:var(--s1);stroke:var(--us)"/>`+T(x,y-1,a,'text-anchor="middle" style="font-size:6.2px;font-weight:800"')+T(x,y+7,b,'text-anchor="middle" style="font-size:5.4px;fill:var(--mut)"'); });
    g+=`<circle cx="100" cy="62" r="24" style="fill:var(--gold);fill-opacity:.9"/>`+T(100,60,'Cạnh tranh','text-anchor="middle" style="font-size:6.2px;font-weight:800;fill:var(--gold-ink)"')+T(100,68,'trong ngành','text-anchor="middle" style="font-size:6.2px;font-weight:800;fill:var(--gold-ink)"');
    return sv(g,'Mô hình năm áp lực cạnh tranh của Porter'); },
  f:'Ngành có lợi nhuận cao bền vững khi cả 5 áp lực đều yếu',
  pts:['Đối thủ mới: ngành cần giấy phép, vốn lớn, mạng lưới (ngân hàng, cảng biển, sân bay) khó bị gia nhập hơn ngành dễ mở (quán cà phê, may mặc).','Sản phẩm thay thế: dịch vụ có thể bị công nghệ khác thay thế làm trần giá bị khống chế.','Nhà cung cấp mạnh (một nguồn nguyên liệu duy nhất) ép biên lợi nhuận; khách hàng mạnh (vài khách lớn chiếm phần lớn doanh thu) ép giá bán.','Cạnh tranh trong ngành: sản phẩm giống nhau, nhiều đối thủ, chi phí cố định cao (thép, phân bón, vận tải) → chiến tranh giá, lợi nhuận theo chu kỳ.','Ngành chu kỳ (thép, hóa chất, vận tải biển, chứng khoán) thường có P/E thấp nhất ở đỉnh lợi nhuận và cao nhất ở đáy — ngược trực giác.','Dùng bản đồ ngành trên trang chủ để so sánh điểm La Bàn bình quân từng ngành.'],
  thr:[['Rào cản gia nhập cao','Lợi nhuận bền hơn'],['Top 3 khách hàng trên 50% doanh thu','Rủi ro tập trung'],['Ngành chu kỳ','Đừng mua vì P/E thấp ở đỉnh chu kỳ']],
  hook:'<b>Mẹo nhớ:</b> một thuyền trưởng giỏi khó thắng nổi con sóng của cả ngành.',src:'Porter (1979), How Competitive Forces Shape Strategy, Harvard Business Review; Porter (2008), The Five Competitive Forces That Shape Strategy, HBR.'},
 {id:'l7-mgmt',t:'Ban lãnh đạo, cổ đông và quản trị',d:'Họ có ngồi cùng thuyền với bạn không',
  vis:()=>{ const it=[['Lãnh đạo sở hữu nhiều cổ phần','y'],['Kế hoạch ĐHĐCĐ thường đạt','y'],['Cổ tức tiền đều đặn','y'],['Phát hành, pha loãng liên tục','n'],['Cổ phiếu lãnh đạo bị cầm cố','n'],['Giao dịch lớn với công ty người nhà','n']];
    let g=''; it.forEach(([t,k],i)=>{ const y=12+i*17; g+=`<rect x="10" y="${y-9}" width="180" height="14" rx="4" style="fill:var(--s1);stroke:var(--line)"/><circle cx="20" cy="${y-2}" r="5" style="fill:${k==='y'?'var(--up)':'var(--dn)'}"/>`+T(20,y+1,k==='y'?'✓':'✗','text-anchor="middle" style="font-size:7px;font-weight:800;fill:var(--bg)"')+T(30,y+1,t,'style="font-size:7.2px"'); });
    g+=T(100,118,'Xanh: dấu hiệu tốt · Đỏ: dấu hiệu cần cảnh giác','text-anchor="middle" '+TS);
    return sv(g,'Danh sách kiểm tra quản trị doanh nghiệp'); },
  f:'Quản trị tốt = Lợi ích lãnh đạo gắn với cổ đông + Phân bổ vốn hợp lý + Minh bạch thông tin',
  pts:['Đọc báo cáo thường niên và thư của chủ tịch/CEO qua nhiều năm: họ có nói thật về khó khăn, có làm đúng điều đã hứa không.','So sánh kế hoạch lợi nhuận đại hội cổ đông với kết quả thực hiện 3–5 năm.','Phân bổ vốn: tiền lãi được dùng để mở rộng hiệu quả (ROIC cao), trả cổ tức, hay đổ vào dự án ngoài ngành, cho bên liên quan vay.','Theo dõi giao dịch của cổ đông nội bộ (bắt buộc công bố): lãnh đạo mua vào thường là tín hiệu tốt hơn bán ra.','Cổ phiếu lãnh đạo cầm cố vay ký quỹ có thể bị bán giải chấp hàng loạt khi thị trường giảm — đã xảy ra nhiều lần ở Việt Nam.','Phát hành ESOP quá nhiều, thù lao lãnh đạo tăng khi lợi nhuận giảm là dấu hiệu lợi ích không đồng hướng.'],
  thr:[['Lãnh đạo sở hữu trên 5–10%','Cùng thuyền với cổ đông'],['ESOP trên 1–2% mỗi năm','Pha loãng đáng kể'],['Đạt kế hoạch 4/5 năm','Lãnh đạo đáng tin về dự báo']],
  hook:'<b>Mẹo nhớ:</b> đầu tư vào doanh nghiệp là thuê ban lãnh đạo quản lý tiền của bạn — hãy phỏng vấn họ qua những gì họ đã làm.',src:'Nghị định 155/2020/NĐ-CP (quản trị công ty đại chúng); G20/OECD Principles of Corporate Governance (2023).'},
 {id:'l7-sector',t:'Đọc BCTC theo ngành',d:'Mỗi ngành có chỉ số riêng',
  vis:()=>{ const c=[['Ngân hàng','var(--us)',['NIM, nợ xấu','CASA, CAR']],['Bất động sản','var(--gold)',['Người mua trả trước','Tồn kho, quỹ đất']],['Bán lẻ','var(--up)',['Doanh thu/cửa hàng','Vòng quay tồn kho']],['Sản xuất','var(--dn)',['Biên gộp, công suất','Giá đầu vào, capex']],['Chứng khoán','var(--vn)',['Dư nợ margin','Tự doanh, thị phần']],['Tiện ích, điện','var(--mut)',['Sản lượng, giá bán','Nợ dự án, khấu hao']]];
    let g=''; c.forEach(([n,col,l],i)=>{ const x=4+(i%3)*65, y=6+Math.floor(i/3)*58; g+=`<rect x="${x}" y="${y}" width="62" height="52" rx="7" style="fill:var(--s1);stroke:${col}"/>`+T(x+31,y+14,n,`text-anchor="middle" style="font-size:7.4px;font-weight:800;fill:${col}"`)+l.map((t,k)=>T(x+31,y+28+k*10,t,'text-anchor="middle" style="font-size:5.4px"')).join(''); });
    return sv(g,'Các chỉ số đặc thù theo ngành'); },
  f:'So sánh doanh nghiệp với đối thủ cùng ngành, dùng chỉ số đặc thù của ngành đó',
  pts:['Ngân hàng: không dùng biên gộp, nợ/vốn. Xem NIM (biên lãi thuần), tỷ lệ nợ xấu và nợ nhóm 2, CASA (tiền gửi không kỳ hạn), CAR (hệ số an toàn vốn), chi phí tín dụng, P/B.','Bất động sản: “người mua trả tiền trước” là doanh thu tương lai; hàng tồn kho là dự án; quỹ đất sạch, pháp lý dự án và nợ vay đến hạn quyết định rủi ro. Lợi nhuận theo đợt bàn giao nên rất thất thường.','Bán lẻ: tăng trưởng doanh thu trên mỗi cửa hàng cũ (same-store sales), vòng quay tồn kho, chi phí thuê trên doanh thu.','Sản xuất hàng hóa (thép, phân bón, hóa chất): biên gộp phụ thuộc giá nguyên liệu và giá bán thế giới; định giá theo chu kỳ.','Chứng khoán: dư nợ cho vay margin, danh mục tự doanh (lãi lỗ theo thị trường), thị phần môi giới.','Bảo hiểm, ngân hàng thường có Altman Z và Piotroski kém ý nghĩa — La Bàn đã tách ngân hàng ra so với ngân hàng.'],
  thr:[['Ngân hàng: nợ xấu dưới 1,5%','Chất lượng tài sản tốt'],['BĐS: người mua trả trước tăng','Doanh thu tương lai được bảo đảm'],['Bán lẻ: vòng quay tồn kho giảm','Hàng chậm bán']],
  hook:'<b>Mẹo nhớ:</b> đừng dùng thước đo của tiệm phở để đo ngân hàng.',src:'Thông tư 41/2016/TT-NHNN (tỷ lệ an toàn vốn); Damodaran, The Dark Side of Valuation (2018).'},
 {id:'l7-styles',t:'Bốn phong cách chọn cổ phiếu',d:'Giá trị, tăng trưởng giá hợp lý, tăng trưởng, cổ tức',act:'styles',
  vis:()=>{ let g=`<line class="axis" x1="22" x2="190" y1="108" y2="108"/><line class="axis" x1="22" x2="22" y1="10" y2="108"/><line x1="106" x2="106" y1="10" y2="108" style="stroke:var(--line2)" stroke-dasharray="3 3"/><line x1="22" x2="190" y1="59" y2="59" style="stroke:var(--line2)" stroke-dasharray="3 3"/>`;
    const q=[[64,32,'GARP','tăng nhanh, giá hợp lý','var(--gold)'],[148,32,'Tăng trưởng','tăng nhanh, giá cao','var(--up)'],[64,82,'Giá trị · Cổ tức','rẻ, tăng chậm','var(--us)'],[148,82,'Cẩn thận','đắt mà tăng chậm','var(--dn)']];
    q.forEach(([x,y,a,b,c])=>{ g+=T(x,y,a,`text-anchor="middle" style="font-size:8.5px;font-weight:800;fill:${c}"`)+T(x,y+10,b,'text-anchor="middle" style="font-size:6px"'); });
    g+=T(106,121,'Định giá: rẻ ← → đắt','text-anchor="middle" '+TS)+`<text transform="translate(12 60) rotate(-90)" text-anchor="middle" style="font-size:6.5px">Tăng trưởng →</text>`;
    return sv(g,'Bản đồ bốn phong cách chọn cổ phiếu theo định giá và tăng trưởng'); },
  f:'Chọn một phong cách hợp tính cách, áp dụng nhất quán — đổi phong cách theo phong trào là cách thua nhanh nhất',
  pts:['Giá trị (Graham): mua doanh nghiệp đang rẻ so với tài sản, lợi nhuận: P/E thấp, P/B thấp, bảng cân đối an toàn. Rủi ro: “bẫy giá trị” — rẻ vì đang suy yếu.','GARP (Lynch): tăng trưởng với giá hợp lý, PEG dưới 1. Cân bằng giữa hai trường phái.','Tăng trưởng (Fisher, O’Neil): doanh thu, EPS tăng nhanh, ROE cao; chấp nhận P/E cao. Rủi ro: giá giảm mạnh khi tăng trưởng chậm lại.','Cổ tức: dòng tiền đều, tỷ suất cao, chi trả bền vững — hợp với tích sản và người cần thu nhập.','Chất lượng (Buffett): ROIC cao bền vững, ít nợ, hào kinh tế — kết hợp được với cả bốn phong cách.','Bấm các nút bên dưới để áp dụng bộ trọng số tương ứng trong bộ lọc La Bàn.'],
  thr:[['Giá trị','P/E dưới 12, P/B dưới 1,5, F-Score từ 6'],['Tăng trưởng','EPS 3 năm trên 20%/năm, ROE trên 18%'],['Cổ tức','Tỷ suất trên 4%, chi trả dưới 70%, FCF lớn hơn cổ tức'],['Chất lượng','ROIC trên 15%, nợ ÷ vốn dưới 0,5']],
  hook:'<b>Mẹo nhớ:</b> phong cách nào cũng có năm thắng năm thua — kỷ luật mới là lợi thế.',src:'Graham, The Intelligent Investor (1973); Lynch, One Up on Wall Street (1989); Fama & French (1992), The Cross-Section of Expected Stock Returns, Journal of Finance 47(2).'},
 {id:'l7-thesis',t:'Luận điểm đầu tư và khi nào bán',d:'Viết ra trước khi mua',
  vis:()=>{ const r=[['Tôi mua vì…','3 lý do có số liệu'],['Giá trị hợp lý…','và biên an toàn'],['Tôi sai nếu…','điều kiện đo được'],['Tôi bán khi…','luận điểm sai, giá quá cao'],['Tỷ trọng…','tối đa bao nhiêu %']];
    let g=`<rect x="22" y="6" width="156" height="112" rx="8" style="fill:var(--s1);stroke:var(--gold)"/>`+T(100,18,'PHIẾU LUẬN ĐIỂM ĐẦU TƯ','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--gold)"');
    r.forEach(([a,b],i)=>{ const y=34+i*17; g+=T(30,y,a,'style="font-size:7px;font-weight:800"')+T(170,y,b,'text-anchor="end" style="font-size:6px;fill:var(--mut)"')+`<line x1="30" x2="170" y1="${y+4}" y2="${y+4}" style="stroke:var(--line2)" stroke-dasharray="2 2"/>`; });
    return sv(g,'Mẫu phiếu luận điểm đầu tư'); },
  f:'Bán khi: luận điểm sai · giá vượt xa giá trị · có cơ hội tốt hơn rõ rệt · cần tiền theo kế hoạch — không bán chỉ vì giá giảm',
  pts:['Viết luận điểm trong 5 dòng trước khi mua: vì sao doanh nghiệp tốt, vì sao giá hấp dẫn, chất xúc tác, rủi ro chính, điều kiện bán.','“Tôi sai nếu…” phải đo được: ví dụ “biên gộp giảm dưới 20% hai quý liên tiếp” hoặc “dự án X chậm quá 12 tháng”.','Giá giảm không phải lý do bán nếu luận điểm còn đúng — có khi là cơ hội mua thêm. Giá tăng mạnh cũng không phải lý do bán nếu giá trị doanh nghiệp tăng theo.','Cắt lỗ theo phần trăm (ví dụ −8%) phù hợp với giao dịch ngắn hạn theo kỹ thuật; nhà đầu tư dài hạn cắt lỗ khi luận điểm gãy.','Xem lại luận điểm mỗi khi có BCTC quý. Ghi nhật ký: quyết định đúng sai vì lý do gì — đây là cách học nhanh nhất.'],
  thr:[['Luận điểm còn đúng, giá giảm','Giữ hoặc mua thêm theo tỷ trọng kế hoạch'],['Luận điểm gãy','Bán, kể cả khi đang lỗ'],['Giá vượt giá trị hợp lý 30%+','Cân nhắc chốt một phần']],
  hook:'<b>Mẹo nhớ:</b> nếu không viết được lý do mua trong 5 dòng, bạn chưa hiểu doanh nghiệp đủ để mua.',src:'Fisher, Common Stocks and Uncommon Profits (1958); Lynch, One Up on Wall Street (1989); Marks, The Most Important Thing (2011).'},
 /* ---------- cấp 8: tích sản ---------- */
 {id:'l8-plan',t:'Kế hoạch tích sản',d:'Góp đều + lãi kép + thời gian',interactive:'fv',
  vis:()=>{ const m=5, r=Math.pow(1.1,1/12)-1; const X=y=>16+y*8.6, Y=v=>104-v/4200*92; let c='',f='';
    for(let y=0;y<=20;y++){ const n=y*12, fv=n? m*((Math.pow(1+r,n)-1)/r):0, ct=m*n; c+=(y?'L':'M')+X(y)+' '+Y(ct); f+=(y?'L':'M')+X(y)+' '+Y(fv); }
    let g=`<path d="${f} L${X(20)} ${Y(0)} L${X(0)} ${Y(0)} Z" style="fill:var(--up);fill-opacity:.35"/><path d="${c} L${X(20)} ${Y(0)} L${X(0)} ${Y(0)} Z" style="fill:var(--us);fill-opacity:.55"/><line class="axis" x1="${X(0)}" x2="${X(20)}" y1="${Y(0)}" y2="${Y(0)}"/>`;
    [0,5,10,15,20].forEach(y=>g+=T(X(y),114,y+' năm','text-anchor="middle" style="font-size:6px"'));
    g+=T(X(20),Y(3591)-4,'≈ 3,6 tỷ','text-anchor="end" style="font-size:8px;font-weight:800;fill:var(--up)"')+T(X(20),Y(1200)-4,'1,2 tỷ tiền góp','text-anchor="end" style="font-size:7px;font-weight:700;fill:var(--us)"');
    g+=T(16,12,'5 triệu/tháng · 10%/năm','style="font-size:7.5px;font-weight:800"')+T(16,22,'Xanh lá: lãi kép làm ra · Xanh lam: tiền bạn góp','style="font-size:6.3px"');
    return sv(g,'Tích sản 5 triệu mỗi tháng trong 20 năm với lợi nhuận 10% mỗi năm'); },
  f:'Giá trị tương lai = Góp mỗi tháng × [(1 + r)ⁿ − 1] ÷ r  (r: lợi nhuận mỗi tháng, n: số tháng)',
  pts:['Tích sản là tích lũy tài sản sinh lời đều đặn trong nhiều năm, không phải tìm một cổ phiếu tăng gấp 10 lần.','Ba đòn bẩy: số tiền góp (tỷ lệ tiết kiệm), lợi nhuận, và thời gian — thời gian là đòn bẩy mạnh nhất vì lãi kép.','Thứ tự ưu tiên: quỹ khẩn cấp 3–6 tháng chi tiêu → trả hết nợ lãi cao (thẻ tín dụng, vay tiêu dùng) → góp định kỳ vào danh mục.','Tự động hóa: chuyển tiền ngay ngày nhận lương; tăng khoản góp mỗi khi thu nhập tăng; tái đầu tư toàn bộ cổ tức.','Đừng ngắt quãng: rút tiền giữa chừng hoặc ngừng góp khi thị trường giảm là cách phá lãi kép hiệu quả nhất.','Dùng máy tính bên dưới để thử số tiền, thời gian và lợi nhuận của bạn; kết quả có cả giá trị quy về tiền hôm nay (đã trừ lạm phát).'],
  thr:[['Tỷ lệ tiết kiệm','Từ 20% thu nhập trở lên'],['Lợi nhuận giả định thận trọng','6–8%/năm cho danh mục cân bằng'],['Xem lại kế hoạch','Mỗi năm một lần, không phải mỗi ngày']],
  hook:'<b>Mẹo nhớ:</b> người thắng trong tích sản không phải người chọn mã giỏi nhất, mà người không bỏ cuộc lâu nhất.',src:'Công thức giá trị tương lai của chuỗi tiền đều (annuity); Bogle, The Little Book of Common Sense Investing (2017).'},
 {id:'l8-alloc',t:'Phân bổ tài sản',d:'Quyết định quan trọng nhất của danh mục',
  vis:()=>{ const P=[['Thận trọng',[30,50,10,10]],['Cân bằng',[60,30,5,5]],['Tăng trưởng',[85,10,5,0]]], C=['var(--up)','var(--us)','var(--mut)','var(--gold)']; let g='';
    P.forEach(([n,a],k)=>{ const cx=34+k*66, cy=50, R=24; let ang=-Math.PI/2; a.forEach((v,i)=>{ if(!v) return; const e=ang+v/100*2*Math.PI; const x1=cx+R*Math.cos(ang), y1=cy+R*Math.sin(ang), x2=cx+R*Math.cos(e), y2=cy+R*Math.sin(e); g+=`<path d="M${cx} ${cy} L${x1.toFixed(1)} ${y1.toFixed(1)} A${R} ${R} 0 ${v>50?1:0} 1 ${x2.toFixed(1)} ${y2.toFixed(1)} Z" style="fill:${C[i]};fill-opacity:.8;stroke:var(--s1)" stroke-width="1"/>`; ang=e; });
      g+=`<circle cx="${cx}" cy="${cy}" r="11" style="fill:var(--s1)"/>`+T(cx,cy+3,a[0]+'%','text-anchor="middle" style="font-size:7px;font-weight:800"')+T(cx,88,n,'text-anchor="middle" style="font-size:7.5px;font-weight:800"'); });
    ['Cổ phiếu','Trái phiếu, tiền gửi','Tiền mặt','Vàng'].forEach((t,i)=>{ const x=30+(i%2)*80, y=100+Math.floor(i/2)*11; g+=`<rect x="${x}" y="${y}" width="7" height="7" rx="2" style="fill:${C[i]}"/>`+T(x+10,y+6.5,t,'style="font-size:6.4px"'); });
    g+=T(100,12,'Ba danh mục mẫu','text-anchor="middle" '+TB);
    return sv(g,'Ba danh mục phân bổ tài sản mẫu'); },
  f:'Quy tắc ngón tay cái: % cổ phiếu ≈ 110 − tuổi, rồi điều chỉnh theo khẩu vị rủi ro và mục tiêu',
  pts:['Phân bổ tài sản là chia tiền giữa các nhóm: cổ phiếu, trái phiếu/tiền gửi, tiền mặt, vàng, bất động sản. Nghiên cứu kinh điển cho thấy phần lớn mức biến động của danh mục đến từ quyết định này, không phải từ việc chọn mã.','Cổ phiếu: động cơ tăng trưởng. Trái phiếu, tiền gửi: giảm biến động, có tiền mua khi thị trường giảm. Vàng: phòng hộ khủng hoảng, lạm phát. Tiền mặt: thanh khoản.','Đa dạng hóa theo địa lý: kết hợp cổ phiếu Việt Nam và quốc tế giúp không phụ thuộc một nền kinh tế.','Bất động sản thường chiếm phần lớn tài sản của người Việt — tính cả nó khi quyết định tỷ trọng cổ phiếu.','Tỷ trọng cổ phiếu giảm dần khi gần đến ngày cần tiền (ví dụ nghỉ hưu, mua nhà) — gọi là đường trượt (glide path).'],
  thr:[['30 tuổi, chưa cần tiền 20 năm','70–90% cổ phiếu'],['50 tuổi','50–60% cổ phiếu'],['Cần tiền trong 3 năm','Dưới 30% cổ phiếu cho khoản đó']],
  hook:'<b>Mẹo nhớ:</b> chọn đúng giỏ quan trọng hơn chọn đúng quả trứng.',src:'Brinson, Hood & Beebower (1986), Determinants of Portfolio Performance, Financial Analysts Journal 42(4); Vanguard Research, The global case for strategic asset allocation (2023).'},
 {id:'l8-rebal',t:'Tái cân bằng danh mục',d:'Bán cao, mua thấp một cách kỷ luật',
  vis:()=>{ const bars=[['Mục tiêu',60],['Sau khi cổ phiếu tăng',72],['Sau tái cân bằng',60]]; let g='';
    bars.forEach(([n,v],i)=>{ const x=20+i*60; g+=`<rect x="${x}" y="${20}" width="34" height="${v*0.8}" rx="2" style="fill:var(--up);fill-opacity:.75"/><rect x="${x}" y="${20+v*0.8}" width="34" height="${(100-v)*0.8}" rx="2" style="fill:var(--us);fill-opacity:.6"/>`+T(x+17,20+v*0.4,v+'%','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--bg)"')+T(x+17,20+v*0.8+(100-v)*0.4+3,(100-v)+'%','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--bg)"')+T(x+17,110,n.split(' ').slice(0,2).join(' '),'text-anchor="middle" style="font-size:6.3px"')+T(x+17,118,n.split(' ').slice(2).join(' '),'text-anchor="middle" style="font-size:6.3px"'); });
    g+=T(100,12,'Xanh lá: cổ phiếu · Xanh lam: trái phiếu, tiền gửi','text-anchor="middle" style="font-size:6.8px"');
    return sv(g,'Tỷ trọng cổ phiếu trôi lên 72% rồi được tái cân bằng về 60%'); },
  f:'Tái cân bằng khi tỷ trọng lệch quá ±5 điểm % so với mục tiêu, hoặc định kỳ mỗi năm một lần',
  pts:['Khi cổ phiếu tăng mạnh, tỷ trọng cổ phiếu vượt mục tiêu → danh mục rủi ro hơn bạn định. Tái cân bằng là bán bớt phần đã tăng, mua phần đã giảm.','Đây là cách “mua thấp bán cao” có kỷ luật, không cần dự đoán thị trường.','Cách rẻ nhất: dùng tiền góp mới và cổ tức để mua phần đang thiếu thay vì bán (tránh thuế, phí).','Định kỳ (mỗi năm) hoặc theo ngưỡng (lệch ±5 điểm %) đều hiệu quả; tái cân bằng quá thường xuyên chỉ tốn phí.','Áp dụng cả bên trong danh mục cổ phiếu: một mã tăng lên chiếm quá 15–20% danh mục thì cân nhắc giảm.'],
  thr:[['Lệch dưới 5 điểm %','Để yên'],['Lệch trên 5 điểm %','Tái cân bằng'],['Một mã vượt 20% danh mục','Rủi ro tập trung — cân nhắc giảm']],
  hook:'<b>Mẹo nhớ:</b> tái cân bằng là kỷ luật bán lúc mọi người tham và mua lúc mọi người sợ — nhưng theo lịch, không theo cảm xúc.',src:'Vanguard Research, Best practices for portfolio rebalancing (2022 update); Swensen, Unconventional Success (2005).'},
 {id:'l8-dividend',t:'Tích sản bằng cổ tức',d:'Tái đầu tư cổ tức và lợi suất trên giá vốn',
  vis:()=>{ let g=''; const yrs=[0,2,4,6,8,10]; yrs.forEach((y,i)=>{ const sh=1000*Math.pow(1.06,y), x=14+i*31, h=sh/1800*62; g+=`<rect x="${x}" y="${94-h}" width="22" height="${h}" rx="2" style="fill:var(--gold);fill-opacity:${.45+i*.1}"/>`+T(x+11,90-h,Math.round(sh),'text-anchor="middle" style="font-size:6.8px;font-weight:700"')+T(x+11,103,'năm '+y,'text-anchor="middle" style="font-size:6px"'); });
    g+=T(100,10,'1.000 cổ phiếu, cổ tức 6%/năm, tái đầu tư toàn bộ','text-anchor="middle" style="font-size:7px;font-weight:800"')+T(100,116,'Số cổ phiếu tăng ≈ 79% sau 10 năm, chưa tính giá tăng','text-anchor="middle" '+TS);
    return sv(g,'Tái đầu tư cổ tức làm số cổ phiếu tăng dần'); },
  f:'Lợi suất trên giá vốn = Cổ tức mỗi cổ phiếu hiện tại ÷ Giá mua ban đầu · Tổng lợi nhuận = Tăng giá + Cổ tức',
  pts:['Tái đầu tư cổ tức (mua thêm cổ phiếu bằng tiền cổ tức) làm số cổ phiếu tự tăng — cộng hưởng với việc doanh nghiệp tăng cổ tức theo thời gian.','Về dài hạn, cổ tức tái đầu tư đóng góp một phần rất lớn vào tổng lợi nhuận của thị trường chứng khoán Mỹ.','Lợi suất trên giá vốn: mua giá 20.000, cổ tức hiện tại 2.000 → 10% trên vốn ban đầu, dù tỷ suất trên giá thị trường chỉ 4%.','Chọn cổ phiếu cổ tức bền: tỷ lệ chi trả dưới 70%, FCF lớn hơn cổ tức, nợ thấp, lịch sử trả đều. Tránh “bẫy cổ tức”: tỷ suất rất cao vì giá đã sập.','Ở Việt Nam, cổ tức tiền mặt bị khấu trừ thuế 5%; cổ tức bằng cổ phiếu không làm bạn giàu hơn ngay lúc chia (giá điều chỉnh tương ứng).'],
  thr:[['Tỷ suất cổ tức 3–6%','Vùng bền vững thường gặp'],['Trên 10%','Kiểm tra: có thể là bẫy cổ tức'],['Tăng cổ tức nhiều năm liền','Dấu hiệu doanh nghiệp chất lượng']],
  hook:'<b>Mẹo nhớ:</b> cổ tức là những “con gà đẻ trứng” — đừng ăn trứng khi đang tích sản, hãy ấp thêm gà.',src:'Siegel, Stocks for the Long Run (6th ed., 2022); S&P Dow Jones Indices, dividend contribution research.'},
 {id:'l8-fire',t:'Tự do tài chính và quy tắc 4%',d:'Cần bao nhiêu tài sản để sống bằng tài sản',
  vis:()=>{ let g=AR2; g+=`<rect x="12" y="34" width="56" height="40" rx="7" style="fill:var(--s1);stroke:var(--us)"/>`+T(40,48,'Chi tiêu/năm','text-anchor="middle" style="font-size:7px;font-weight:800;fill:var(--us)"')+T(40,62,'300 triệu','text-anchor="middle" style="font-size:9px;font-weight:800"');
    g+=T(80,57,'× 25','text-anchor="middle" style="font-size:10px;font-weight:800"');
    g+=`<rect x="94" y="22" width="94" height="64" rx="9" style="fill:var(--gold);fill-opacity:.85"/>`+T(141,42,'Tài sản mục tiêu','text-anchor="middle" style="font-size:7.5px;font-weight:800;fill:var(--gold-ink)"')+T(141,62,'7,5 tỷ','text-anchor="middle" style="font-size:15px;font-weight:800;fill:var(--gold-ink)"')+T(141,76,'rút 4% năm đầu','text-anchor="middle" style="font-size:6.5px;fill:var(--gold-ink)"');
    g+=T(100,104,'Số tiền rút tăng theo lạm phát mỗi năm','text-anchor="middle" '+TS)+T(100,116,'Thận trọng hơn: 3–3,5% (× 29–33)','text-anchor="middle" '+TB);
    return sv(g,'Tài sản mục tiêu bằng chi tiêu một năm nhân 25'); },
  f:'Tài sản mục tiêu ≈ Chi tiêu một năm × 25  (tương ứng rút 4% năm đầu, sau đó tăng theo lạm phát)',
  pts:['Nghiên cứu của Bengen (1994) và “Trinity Study” (1998) trên dữ liệu Mỹ: rút 4% tài sản năm đầu, sau đó điều chỉnh theo lạm phát, danh mục cân bằng cổ phiếu – trái phiếu hầu như đủ dùng 30 năm.','Muốn sống bằng tài sản lâu hơn 30 năm, hoặc thị trường biến động mạnh hơn, nên dùng mức rút thận trọng 3–3,5%.','Ví dụ: chi tiêu 300 triệu/năm → cần khoảng 7,5 tỷ (4%) đến 10 tỷ (3%).','Ghép với bài Kế hoạch tích sản: biết đích đến rồi tính ngược số tiền cần góp mỗi tháng và số năm.','Nguồn thu khác (lương hưu, cho thuê, kinh doanh) làm giảm số tài sản cần có.','Đây là quy tắc kinh nghiệm dựa trên lịch sử Mỹ, không bảo đảm cho tương lai hay cho thị trường Việt Nam.'],
  thr:[['Rút 4%','Tài sản = 25 × chi tiêu'],['Rút 3,5%','≈ 29 × chi tiêu'],['Rút 3%','≈ 33 × chi tiêu']],
  hook:'<b>Mẹo nhớ:</b> tự do tài chính bắt đầu từ việc biết mình tiêu bao nhiêu mỗi năm.',src:'Bengen (1994), Determining Withdrawal Rates Using Historical Data, Journal of Financial Planning; Cooley, Hubbard & Walz (1998), Retirement Savings: Choosing a Withdrawal Rate That Is Sustainable, AAII Journal.'}
];
LESSONS2.forEach(l=>{ l.g='Mở rộng'; LESSONS.push(l); });

